<?php declare(strict_types=1);namespace NpmGateway\Http\Controllers;use NpmGateway\Contracts\CorporateToolsProviderInterface;use NpmGateway\Exceptions\Domain\{CommunityActionPropertyForbiddenException,CommunityActionPropertyNotFoundException,RmAuditStateConflictException};use NpmGateway\Http\{AuthenticatedRequestContext,Request,Response};use NpmGateway\Security\CsrfService;use NpmGateway\Services\{CommunityActionContextResolver,RmAuditQueryService,RmAuditService};use NpmGateway\Support\FlashSession;
final class RmAuditController{public function __construct(private readonly CommunityActionContextResolver$resolver,private readonly RmAuditQueryService$q,private readonly RmAuditService$s,private readonly CorporateToolsProviderInterface$tools,private readonly CsrfService$csrf,private readonly FlashSession$flash,private readonly string$views){}
 public function index(Request$r,string$slug,AuthenticatedRequestContext$c):Response{if(($x=$this->ctx($c,$slug))instanceof Response)return$x;$status=(string)($r->query['status']??'');$search=trim((string)($r->query['search']??''));$audits=$this->q->managerList($x->propertyId,$status,$search);$counts=$this->q->counts($x->propertyId,$status,'',$search);$context=$x;return$this->render('index',$c,compact('audits','counts','status','search','context'));}
 public function show(string$slug,string$p,AuthenticatedRequestContext$c):Response{if(($x=$this->ctx($c,$slug))instanceof Response)return$x;$audit=$this->q->detail($p,$x->propertyId);if(!$audit)return new Response(404,'Not Found');$context=$x;$success=(string)$this->flash->pull('rma_success','');$warning=(string)$this->flash->pull('rma_warning','');$error=(string)$this->flash->pull('rma_error','');return$this->render('show',$c,compact('audit','context','success','warning','error'));}
 public function complete(Request$r,string$slug,string$p,AuthenticatedRequestContext$c):Response{if(($x=$this->ctx($c,$slug))instanceof Response)return$x;if(!$this->csrf->valid($r->post['_token']??null))return new Response(419,'Invalid request.');try{$sent=$this->s->complete($x,$p);$this->flash->put('rma_success','RM Audit marked Completed.');if(!$sent)$this->flash->put('rma_warning','The audit was completed, but the Corporate notification could not be delivered.');}catch(RmAuditStateConflictException){$this->flash->put('rma_error','This audit is no longer eligible for completion.');}catch(\OutOfBoundsException){return new Response(404,'Not Found');}return Response::redirect('/community-actions/'.$slug.'/rm-audits/'.$p);}
 private function ctx(AuthenticatedRequestContext$c,string$s):mixed{try{return$this->resolver->resolve($c,$s);}catch(CommunityActionPropertyNotFoundException){return new Response(404,'Not Found');}catch(CommunityActionPropertyForbiddenException){return new Response(403,'Forbidden');}}private function render(string$v,AuthenticatedRequestContext$c,array$x):Response{$user=$c->user;$csrfToken=$this->csrf->token();$logoutCsrfToken=$csrfToken;$navbarCorporateItems=$this->tools->tools($c);extract($x);ob_start();require$this->views.'/community-actions/rm-audits/'.$v.'.php';return new Response(200,(string)ob_get_clean(),['Cache-Control'=>'private, no-store']);}}
